import { Node } from "../shared/node.ts";
import { formatAttributes } from "./attributes.js";

export class Text extends Node {
  data: string;

  constructor(data: string) {
    super("#text");
    this.data = data;
  }

  override get textContent(): string {
    return this.data;
  }

  override serialize(): string {
    return this.data;
  }
}

export class Element extends Node {
  readonly tagName: string;
  private readonly attributes = new Map<string, string>();

  constructor(tagName: string) {
    super(tagName.toUpperCase());
    this.tagName = tagName;
  }

  setAttribute(name: string, value: string): void {
    this.attributes.set(name, value);
  }

  getAttribute(name: string): string | null {
    return this.attributes.get(name) ?? null;
  }

  override serialize(): string {
    const attrs: string = formatAttributes(this.attributes);
    return `<${this.tagName}${attrs}>${super.serialize()}</${this.tagName}>`;
  }
}

export function createElement(tagName: string): Element {
  return new Element(tagName);
}
